"""Revalidate selected vc257 ARM64 methods, literals and explicit client adaptation boundaries."""
from pathlib import Path
import csv,hashlib,json,struct
from map_game_methods import ROOT as R,native,raw
Q=R/'reports'
rows=list(csv.DictReader((R/'native-boss-sweep-client-reviewed/status.tsv').open(),delimiter='\t'));assert len(rows)==23 and all(x['completed']=='true' and not x['error'] for x in rows)
queries=[x.split('\t') for x in (Q/'native-boss-sweep-client-queries.tsv').read_text().splitlines()];methods=[]
for va,label,prefix,end in queries:
 start=int(va,16);stop=int(end,16);blob=native[raw(start):raw(start)+stop-start];assert native[raw(start):raw(start)+16].hex()==prefix
 for ext in ['c','asm']:assert (R/'native-boss-sweep-client-reviewed'/f'{label}.{ext}').exists()
 methods.append({'preferredVa':va,'end':end,'name':label,'first16':prefix,'sha256':hashlib.sha256(blob).hexdigest(),'completed':True})
