types=json.loads((Q/'resolved-type-schema.json').read_text());shop=next(x for x in types if x['name']=='Shop_manager');f=next(x for x in shop['fields'] if x['name']=='Is_Remove_AD_All');assert f['native_offset']==9
out={'target':'com.Chodun.CatGunner 1.1.61 vc257 ARM64','businessMethods':17,'exceptionHelpers':6,'allQueriesCompleted':True,'methods':methods,'literals':lit,'automaticBonusField':f,'nativeRules':{'entry':'Boss_Start_UI checks PlusPack.Is_Active(2); power gates Game_Sweep. Native manager itself gates power only. No ticket charge or season attempt count.','required':'health/Math.Max(1,(int)Math.Round((double)(maxTime*70f/100f))), ToPrecision(5); float32 expression then nearest-even rounding','previewPower':'active ordinary Cat_list only; skip cooldown<=0.001; ExpectedDamage_Boss*100/(int)(AtkCool_Boss*100); final ToPrecision(5); forest upgrades excluded','expectedDamage':'Gun base *rebirth *skin *fish *relic -> discard ->power buff ->star slot; critical multiplies125+fishCritical and relicCritical then discard; clamped chance weighted mean','settlement':'stage+1 once; ordinary base150 or PlusPack1 base300; AutoBonus pays base*3 immediately; base and triple text retained. Other branch claims base*2 on reward callback.','automaticBonus':'Shop_manager static Is_Remove_AD_All offset9 OR FreeCash_manager.RewardAdRemoved; forced removal offset8 does not auto reward','originalCallback':'Sweep bonus button serialized Bonus_AD_Show -> Bonus_Get -> if pending sweep SweepBonus_Get; normal NoAds Game_Exit; sweep NoAds Sweep_Close'},'adapters':['Shared local purchase/ad simulators authorized by user; no real store/ad SDK or production receipt','FreeCash promotional entitlement remains unavailable; original condition documented, not fabricated','24 guard digits in decimal division and existing original precision5 truncation; not full InfVal fidelity','reject before reward if next health stage exceeds verified 1000-entry cache; no extrapolated health','result revision, current mode/page and in-flight guard reject duplicate/stale local callbacks','quarter-second local UI observer updates expiry/current power; native reload is explicit OnEnable/Reload','trusted server time/ranking submission/interstitial SDK unavailable; no-op or existing disabled online UI boundary'],'scopeComplete':False}
(Q/'boss-sweep-native-contract.json').write_text(json.dumps(out,ensure_ascii=False,indent=2));print({'completed':len(methods),'business':17,'helpers':6,'cooldownThreshold':lit['cooldownThreshold'],'format':lit['format']})
